entries[255613] = { ["name"] = "Galactic Gladiator's Badge of Ferocity", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 13 Critical Strike\nUse: Increases primary stat by 23 for 15 sec. (1 Min Cooldown)\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 5% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[255614] = { ["name"] = "Galactic Gladiator's Insignia of Alacrity", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 13 Haste\nEquip: Your spells and abilities have a chance to grant 19 primary stat for 20 sec.\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 5% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[255615] = { ["name"] = "Galactic Gladiator's Emblem", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 [Agility or Strength or Intellect]\nUse: Increases maximum health by 1008 for 15 sec. (2 Min Cooldown)\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 5% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[255616] = { ["name"] = "Galactic Gladiator's Medallion", ["text"] = "Binds when picked up\nUnique-Equipped: Gladiator's Medallions (1)\nTrinket\n+9 [Agility or Strength or Intellect]\nUse: Removes all movement impairing effects and all effects which cause loss of control of your character.\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 5% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[255617] = { ["name"] = "Galactic Gladiator's Sigil of Adaptation", ["text"] = "Binds when picked up\nUnique-Equipped: Gladiator's Medallions (1)\nTrinket\n+9 [Agility or Strength or Intellect]\nEquip: Removes any loss of control effect with a duration of 5 seconds or more. This effect can only occur once every 1 min.\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 5% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
