entries[257142] = { ["name"] = "Fiery Dragonhawk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Renown Rank 19 with the Silvermoon Court.\n\n\"A dragonhawk whose wings shine as brightly as the leaves of its Eversong home.\"\nVendor:\nCaeris Fairdawn\nZone:\nEversong Woods\nCost:\n8000" }
entries[257143] = { ["name"] = "Peridot Dragonhawk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"Peridot dragonhawks are only awarded to those who have performed great deeds in service of Silvermoon.\"\nWorld Quest:\nFrom Darkness, Light\nZone:\nIsle of Quel'Danas" }
entries[257144] = { ["name"] = "Umbral Dragonhawk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Cloaked in blackened tones, this Dragonhawk glides with calm precision, its somber coloring lending it an air of quiet distinction.\"\nAchievement:\nLife of the Party\nCategory:\nMidnight" }
entries[257145] = { ["name"] = "Crimson Dragonhawk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"A strikingly colored Dragonhawk admired across Quel'Thalas, its vivid red wings cutting bright arcs through the skies as it glides with smooth, effortless grace.\"\nAchievement:\nMidnight Glyph Hunter\nCategory:\nSkyriding" }
entries[257147] = { ["name"] = "Cobalt Dragonhawk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"A rare breed of Dragonhawk that soars the Thalassian skies on azure wings after having escaped from the Sunwing Rookery.\"\nDrop:\nEversong Woods Rare Creatures" }
entries[257149] = { ["name"] = "Old Tome", ["text"] = "\"Its pages brittle and its ink long faded, yet a faint, acrid scent clings to it... as if some diabolic remedy had once been brewed from its secrets.\"\nSell Price:" }
entries[257152] = { ["name"] = "Amani Sharptalon", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"A rare variety of the Amani eagle, Sharptalons strike with terrifying precision and fly with unparalleled grace.\"\nDrop:\nZul'Aman Rare Creatures" }
entries[257154] = { ["name"] = "Crimson Silvermoon Hawkstrider", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Renown Rank 17 with the Silvermoon Court.\n\n\"The pride of the Silvermoon Court, these hawkstriders are prized for their vibrant red plumage and purebred elegance.\"\nVendor:\nCaeris Fairdawn\nZone:\nEversong Woods\nCost:\n6000" }
