entries[257191] = { ["name"] = "Preyseeker's Hubris", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Preyseeker's Journey rank 5\n\n\"Larger mana wyrms are sometimes used as mounts by Blood Elves, but are more frequently kept as status symbols.\"\nVendor:\nConstruct V'anore\nZone:\nSilvermoon City\nCost:\n2000" }
entries[257192] = { ["name"] = "Preyseeker's Wrath", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Preyseeker's Journey rank 10\n\n\"Mana wyrms that are large and strong enough to support full barding and rider are quite rare and highly prized.\"\nVendor:\nConstruct V'anore\nZone:\nSilvermoon City\nCost:\n2550" }
entries[257193] = { ["name"] = "Preyseeker's Nightmare", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Golden mana wyrms are an uncommon mutation. Some of Astalor's side experiments have included efforts to increase their population..\"\nAchievement:\nPrey: Nightmare Mode III\nCategory:\nPrey" }
entries[257194] = { ["name"] = "Artisan's Consortium Flyer", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"A notice promoting a special giveaway in Falconwing Square.\"" }
entries[257197] = { ["name"] = "Blessed Amani Burrower", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"A creature blessed by the wilds, it moves with the steadfast spirit and gentle strength the Amani hold sacred.\"\nVendor:\nChel the Chip\nFeature:\nAbundance\nCost:\n1600" }
entries[257199] = { ["name"] = "Giganto Manis", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Whispers tell of the Giganto Manis, a titanic creature said to dwell within Azeroth's very veins. Those who claim to have seen it speak of claws vast enough to pierce a dragon's heart, and sharp enough to carve through the finest armor forged by mortal hands.\"\nAchievement:\nGlory of the Midnight Delver" }
