entries[257219] = { ["name"] = "Amani Blessed Bear", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Renown Rank 17 with the Amani Tribe.\n\n\"Once symbols of conquest, these war-bears now stride again, reborn through Nalorakk's blessing and the renewed spirit of the Amani.\"\nVendor:\nMagovu\nZone:\nZul'Aman\nCost:\n6000" }
