entries[257223] = { ["name"] = "Ancestral War Bear", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Its tread resounds with the memory of ancient warriors, a living symbol of the unwavering ferocity the Amani revere.\"\nTreasure:\nHonored Warrior's Cache\nZone:\nZul'Aman" }
entries[257225] = { ["name"] = "Witherbark Warbear Harness", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This warbear mother was captured by the Twilight's Blade while protecting her cub. Her continued separation from her cub is only angering her more. Anyone who manages to reunite her with her cub will have her eternal loyalty.\"\nRitual Site:\nBroken Throne" }
